def art(w):
    return "an" if w[0].lower() in "aeiou" else "a"


class World:
    def __init__(self, split="test", seed=None):
        assert split in SEEDS
        self.seed = SEEDS[split] if seed is None else seed
        self.split, self.rng = split, random.Random(self.seed)
        self.slots = DEV_SLOTS + (HELD_OUT_SLOTS if split == "test" else [])
        self.rels = DEV_RELS + (HELD_OUT_RELS if split == "test" else [])
        self.people, self.abstract = [], []
        self._people()
        self._plan()
        self._render()
        self._delete()
        self.questions = self._questions()

    # ------------------------------------------------------------------ people
    def _people(self):
        r = self.rng
        firsts = []
        for f in SAME_FIRST:                                   # 30 first names used twice
            firsts += [f, f]
        for a, b in NEAR_FIRST:                                # 20 near-name pairs
            firsts += [a, b]
        n = N_CLOSE + N_OTHER
        pool = [f for f in OTHER_FIRST if f not in firsts]
        r.shuffle(pool)
        firsts += pool[: n - len(firsts)]
        assert len(firsts) == n, (len(firsts), n)
        r.shuffle(firsts)
        lasts = list(LASTS)
        r.shuffle(lasts)
        used_full = set()
        for i, f in enumerate(firsts):
            last = lasts[i % len(lasts)]
            while f"{f} {last}" in used_full:
                last = r.choice(LASTS)
            used_full.add(f"{f} {last}")
            p = {"id": i, "first": f.rstrip("0123456789"), "last": last, "pron": r.choice(["she", "he", "they"]),
                 "nick": None, "role": None, "circle": None, "close": False, "attrs": {}, "links": []}
            p["full"] = f"{p['first']} {last}"
            self.people.append(p)
        # close people: unique roles to the user; the rest join circles or are known only through someone
        for p, role in zip(self.people[:N_CLOSE], CLOSE_ROLES):
            p["close"], p["role"] = True, role
            if role in ("mum", "sister", "grandma"):
                p["pron"] = "she"
            if role in ("dad", "brother", "uncle"):
                p["pron"] = "he"
        circles = list(CIRCLES)
        for k, p in enumerate(self.people[N_CLOSE:]):
            p["circle"] = circles[k % len(circles)] if k < 170 else None    # 80 known only through someone
        for p in r.sample(self.people, N_NICK):
            p["nick"] = NICKS.pop(r.randrange(len(NICKS))) if NICKS else None
        # attributes: each person gets 4-7 slots (close people: all), each with a value history
        for p in self.people:
            k = len(self.slots) if p["close"] else r.randint(4, min(7, len(self.slots)))
            for s in r.sample(self.slots, k):
                p["attrs"][s] = [self.rng.randrange(len(SLOTS[s]["vals"]))]
        # links: 3-6 per person, by relation type; a person has at most one of each type (so "X's mentor" is unique)
        have = defaultdict(set)                                 # (person, rel) taken
        def can(a, b, rel):
            return a != b and (a, rel) not in have and (b, rel if RELS[rel][0] else "~" + rel) not in have
        order = list(range(len(self.people)))
        for a in order:
            want = r.randint(3, 6)
            tries = 0
            while sum(1 for x in self.people[a]["links"]) < want and tries < 60:
                tries += 1
                rel = r.choice(self.rels)
                b = r.randrange(len(self.people))
                if not can(a, b, rel):
                    continue
                have[(a, rel)].add(b)
                have[(b, rel if RELS[rel][0] else "~" + rel)].add(a)
                self.people[a]["links"].append((rel, b, "out"))
                self.people[b]["links"].append((rel, a, "in"))

    # ------------------------------------------------------------------ abstract notes on a timeline
    def _day(self, lo=0, hi=None):
        span = (END - START).days
        return START + dt.timedelta(days=self.rng.randint(lo, span if hi is None else hi))

    def _plan(self):
        r, A = self.rng, self.abstract
        span = (END - START).days
        self.intro_day = {}
        for p in self.people:                                   # introductions: close people early, others spread
            d = self._day(0, 40) if p["close"] else self._day(0, span - 200)
            self.intro_day[p["id"]] = d
            A.append({"date": d, "type": "intro", "p": p["id"], "order": 0})
            if p["nick"]:
                A.append({"date": d + dt.timedelta(days=r.randint(1, 30)), "type": "nick", "p": p["id"], "order": 1})
        for p in self.people:                                   # facts: first value, then changes over time
            for s, hist in p["attrs"].items():
                d0 = self.intro_day[p["id"]] + dt.timedelta(days=r.randint(2, 60))
                A.append({"date": d0, "type": "fact", "p": p["id"], "slot": s, "vi": hist[0], "form": "init"})
                n_changes = (r.choice([0, 1, 1, 2, 3]) if p["close"] else r.choice([0, 0, 0, 1]))
                if SLOTS[s]["change"] is None:
                    n_changes = 0
                d = d0
                for _ in range(n_changes):
                    d = d + dt.timedelta(days=r.randint(20, 120))
                    if d >= END:
                        break
                    vi = r.choice([i for i in range(len(SLOTS[s]["vals"])) if i not in hist])
                    form = r.choice(["plain", "change", "fix"])
                    A.append({"date": d, "type": "fact", "p": p["id"], "slot": s, "vi": vi, "form": form,
                              "old": hist[-1]})
                    hist.append(vi)
                gone = END + dt.timedelta(days=1)
                if SLOTS[s]["retract"] and r.random() < (0.15 if p["close"] else 0.09):
                    dd = d + dt.timedelta(days=r.randint(30, 150))
                    if dd < END:
                        A.append({"date": dd, "type": "retract", "p": p["id"], "slot": s})
                        p.setdefault("retracted", {})[s] = dd
                        gone = dd
                if p["close"] and r.random() < 0.6:            # repeat the current value later (fan, no change),
                    for _ in range(r.randint(2, 6)):           # never after a retraction
                        dd = d + dt.timedelta(days=r.randint(5, 200))
                        if dd < min(END, gone):
                            A.append({"date": dd, "type": "fact", "p": p["id"], "slot": s, "vi": hist[-1],
                                      "form": "repeat"})
            for _ in range(r.randint(25, 45) if p["close"] else r.randint(0, 2)):   # lures (never the current value)
                s = r.choice(self.slots)
                cur = p["attrs"].get(s, [None])
                vi = r.choice([i for i in range(len(SLOTS[s]["vals"])) if i not in cur])
                A.append({"date": self._day((self.intro_day[p["id"]] - START).days + 1), "type": "lure",
                          "p": p["id"], "slot": s, "vi": vi})
            for _ in range(r.randint(120, 170) if p["close"] else r.randint(0, 2)):  # everyday mentions, no facts
                A.append({"date": self._day((self.intro_day[p["id"]] - START).days + 1), "type": "small", "p": p["id"]})
        for p in self.people:                                   # relation notes (once per link, from either side)
            for rel, b, way in p["links"]:
                if way != "out":
                    continue
                d = max(self.intro_day[p["id"]], self.intro_day[b]) + dt.timedelta(days=r.randint(1, 90))
                if d >= END:
                    d = END - dt.timedelta(days=1)
                A.append({"date": d, "type": "rel", "p": p["id"], "q": b, "rel": rel, "rev": r.random() < 0.5})
        for p in self.people:                                   # events: in-person meetings with the user
            for _ in range(r.randint(10, 22) if p["close"] else r.choice([0, 0, 1, 1, 2])):
                d = self._day((self.intro_day[p["id"]] - START).days + 1)
                A.append({"date": d, "type": "event", "p": p["id"], "act": r.randrange(len(ACTIVITIES)),
                          "when": r.choice(["today", "yesterday", "weekday", "explicit"])})
        for _ in range(250):
            A.append({"date": self._day(), "type": "noise"})
        for a in A:
            if a["date"] > END:
                a["date"] = END
        A.sort(key=lambda a: (a["date"], a.get("order", 2)))

    # ------------------------------------------------------------------ rendering in time order
    def _mention(self, pid, ctx, allow_pron=False, cap=False, via_ok=True):
        """Pick how a person is mentioned, given what has been said so far; returns (text, style)."""
        r, p = self.rng, self.people[pid]
        styles = [("full", 25)]
        if p["role"]:
            styles.append(("role", 30))
        if p["nick"] and p["nick_known"]:
            styles.append(("nick", 12))
        fc = (p["first"], p["circle"])
        if p["circle"] and self.known_fc[fc] == {pid}:
            styles.append(("fname_ctx", 15))
        recent = [x for x in ctx["recent"][-3:]]
        same_first_recent = [q for q in ctx["recent"][-10:] if self.people[q]["first"] == p["first"] and q != pid]
        if self.known_first[p["first"]] == {pid} or (pid in recent and not same_first_recent):
            styles.append(("fname", 15))
        via = [(rel, b) for rel, b, way in p["links"] if self.link_known.get((b, rel, pid)) and
               self.unique_link(b, rel)]
        if via and via_ok:
            styles.append(("via", 6))
        names, weights = zip(*styles)
        st = r.choices(names, weights)[0]
        if st == "full":
            t = p["full"]
        elif st == "role":
            t = f"my {p['role']}"
        elif st == "nick":
            t = p["nick"]
        elif st == "fname_ctx":
            t = f"{p['first']} {CIRCLES[p['circle']][0]}"
        elif st == "fname":
            t = p["first"]
        else:
            rel, b = r.choice(via)
            bt, _ = self._mention(b, ctx, via_ok=False)
            t = f"{bt}'s {RELS[rel][3]}"
            st = "via"
        return (t[0].upper() + t[1:] if cap else t), st

    def unique_link(self, b, rel):
        return sum(1 for rr, _, _ in self.people[b]["links"] if rr == rel) == 1

    def _render(self):
        r = self.rng
        self.known_first, self.known_fc = defaultdict(set), defaultdict(set)
        self.link_known = {}
        for p in self.people:
            p["nick_known"] = False
        ctx = {"recent": []}
        self.notes = []
        for a in self.abstract:
            pid = a.get("p")
            p = self.people[pid] if pid is not None else None
            facts, mentions = [], []
            d = a["date"]
            if a["type"] == "intro":
                self.known_first[p["first"]].add(pid)
                if p["circle"]:
                    self.known_fc[(p["first"], p["circle"])].add(pid)
                if p["role"]:
                    text = r.choice([f"My {p['role']} {p['full']} called today.",
                                     f"Having lunch with my {p['role']}, {p['full']}, this weekend."])
                    facts.append((pid, "relation to me", p["role"]))
                elif p["circle"]:
                    c = CIRCLES[p["circle"]]
                    text = r.choice([f"Met {p['full']} {c[2]} today.", f"{p['full']} is {c[1]}."])
                    facts.append((pid, "known from", p["circle"]))
                else:
                    text = r.choice([f"Got introduced to {p['full']} at a party.",
                                     f"Met {p['full']}, a friend of a friend."])
                    facts.append((pid, "known from", "a party"))
                mentions.append((p["full"], pid, "full"))
            elif a["type"] == "nick":
                m, st = self._mention(pid, ctx)
                o = PRON[p["pron"]][1]
                text = f"Everyone calls {m if st != 'full' else p['full']} \"{p['nick']}\" - I'll call {o} that too."
                if not text.startswith("Everyone"):
                    text = text
                facts.append((pid, "nickname", p["nick"]))
                mentions.append((m, pid, st))
                p["nick_known"] = True
            elif a["type"] in ("fact", "lure", "retract", "small"):
                m, st = self._mention(pid, ctx)
                pr = PRON[p["pron"]]
                if a["type"] == "small":
                    tmpl, slot, v = r.choice(SMALL), None, None
                elif a["type"] == "retract":
                    tmpl, slot, v = r.choice(SLOTS[a["slot"]]["retract"]), a["slot"], None
                    facts.append((pid, a["slot"], None))
                else:
                    S = SLOTS[a["slot"]]
                    slot = a["slot"]
                    canon, alt, _ = S["vals"][a["vi"]]
                    if a["type"] == "lure":
                        tmpl = r.choice(S["lures"])
                    else:
                        form = {"init": "init", "repeat": "plain", "plain": "plain", "change": "change",
                                "fix": "fix"}[a["form"]]
                        tmpl = r.choice(S[form])
                        facts.append((pid, slot, canon))
                    v = canon
                use_pron = (a["type"] in ("fact", "retract") and r.random() < 0.18 and st != "via")
                fill = dict(v=v or "", alt=(S["vals"][a["vi"]][1] if a["type"] in ("fact", "lure") else ""),
                            a=art(v) if v else "", pos=pr[2], pfx=pr[0], old="", a2="")
                if a["type"] == "fact" and a["form"] == "fix":
                    old = SLOTS[slot]["vals"][a["old"]][0]
                    fill["old"], fill["a2"] = old, art(old)
                if use_pron:                                    # "Ran into Mira. She works as a pharmacist."
                    opener = r.choice(["Ran into {m} at the shops.", "Caught up with {m}.", "Saw {m} earlier."])
                    body = tmpl.replace("{M}'s", pr[2].capitalize()).replace("{M}", pr[0].capitalize())
                    if p["pron"] == "they":
                        body = (body.replace("They is", "They are").replace("They has", "They have")
                                .replace("They works", "They work").replace("They lives", "They live")
                                .replace("They drives", "They drive").replace("They plays", "They play")
                                .replace("They grows", "They grow").replace("They takes", "They take")
                                .replace("They switched", "They switched").replace("They quit", "They quit"))
                    text = opener.format(m=m if st not in ("role",) else m.lower()) + " " + body.format(**fill)
                    mentions.append((m, pid, st))
                    mentions.append((pr[0], pid, "pronoun"))
                else:
                    text = tmpl.replace("{M}", m).format(**fill) if "{M}" in tmpl else tmpl.format(M=m, **fill)
                    mentions.append((m, pid, st))
            elif a["type"] == "rel":
                b, rel = a["q"], a["rel"]
                sym, fwd, rev, noun = RELS[rel]
                ma, sa = self._mention(pid, ctx)
                mb, sb = self._mention(b, ctx)
                if sa == "via" or sb == "via":                  # keep relation notes to direct mentions
                    ma, sa = self.people[pid]["full"], "full"
                    mb, sb = self.people[b]["full"], "full"
                tmpl = r.choice(rev if a["rev"] else fwd)
                text = tmpl.format(A=ma, B=mb)
                text = text[0].upper() + text[1:]
                facts.append((pid, rel, b))                     # pid is b's <rel> (directed: pid -> b)
                mentions += [(ma, pid, sa), (mb, b, sb)]
                self.link_known[(pid, rel, b)] = True
                self.link_known[(b, rel, pid)] = sym or self.link_known.get((b, rel, pid), False)
                if sym:
                    self.link_known[(b, rel, pid)] = True
            elif a["type"] == "event":
                m, st = self._mention(pid, ctx, cap=False)
                act, phrase = ACTIVITIES[a["act"]]
                if a["when"] == "today":
                    ed, when = d, "today"
                elif a["when"] == "yesterday":
                    ed, when = d - dt.timedelta(days=1), "yesterday"
                elif a["when"] == "weekday":
                    back = r.randint(2, 6)
                    ed = d - dt.timedelta(days=back)
                    when = f"on {WEEKDAYS[ed.weekday()]}"
                else:
                    back = r.randint(2, 12)
                    ed = d - dt.timedelta(days=back)
                    when = f"on {ed.day} {MONTHS[ed.month - 1]}"
                if ed < START:
                    ed, when = d, "today"
                body = phrase.format(W=m)
                text = r.choice([f"{when[0].upper() + when[1:]} I {body}.", f"I {body} {when}."])
                facts.append((pid, "event", (act, ed.isoformat())))
                mentions.append((m, pid, st))
            else:
                text = r.choice(NOISE)
            text = text[0].upper() + text[1:]
            nid = len(self.notes)
            self.notes.append({"id": nid, "date": d.isoformat(), "text": text, "facts": facts,
                               "mentions": mentions, "type": a["type"], "form": a.get("form")})
            for _, q, _ in mentions:
                ctx["recent"].append(q)
            ctx["recent"] = ctx["recent"][-20:]

    # ------------------------------------------------------------------ deletions
    def _delete(self):
        """Delete 100 notes, each the only note stating its (person, slot) fact, never an intro or a relation."""
        src = defaultdict(list)
        for n in self.notes:
            for pid, slot, v in n["facts"]:
                if slot in SLOTS:
                    src[(pid, slot)].append(n["id"])
        # a lure or any other note naming the same value for the same person would keep the fact alive: exclude
        cands = []
        for (pid, slot), ids in src.items():
            if len(ids) != 1 or self.people[pid].get("retracted", {}).get(slot):
                continue
            val = self.notes[ids[0]]["facts"][0][2]
            if val is None:
                continue
            keys = SLOTS[slot]["vals"][[c for c, _, _ in SLOTS[slot]["vals"]].index(val)][2]
            other = [n for n in self.notes if n["id"] != ids[0] and any(m[1] == pid for m in n["mentions"]) and
                     any(k in n["text"].lower() for k in keys)]
            if not other:
                cands.append((pid, slot, ids[0], val))
        self.rng.shuffle(cands)
        self.deleted = cands[:N_DELETE]
        self.deleted_ids = {nid for _, _, nid, _ in self.deleted}

    # ------------------------------------------------------------------ truth after deletion
    def current(self, pid, slot):
        """(value or None, history of earlier values, note ids that establish it); None value = retracted/unknown."""
        hist, nids = [], []
        val = None
        for n in self.notes:
            if n["id"] in self.deleted_ids:
                continue
            for q, s, v in n["facts"]:
                if q == pid and s == slot:
                    if v is not None and v != val and val is not None:
                        hist.append(val)
                    val = v
                    nids.append(n["id"])
        return val, hist, nids

    def intro_note(self, pid):
        return next(n["id"] for n in self.notes if n["type"] == "intro" and n["mentions"][0][1] == pid)

    def nick_note(self, pid):
        return next((n["id"] for n in self.notes if n["type"] == "nick" and n["mentions"][0][1] == pid), None)

    def rel_note(self, a, rel, b):
        return next((n["id"] for n in self.notes if n["type"] == "rel" and n["facts"][0] in ((a, rel, b), (b, rel, a))
                     and n["facts"][0][1] == rel), None)

    def events(self, pid):
        return [(f[2][1], f[2][0], n["id"]) for n in self.notes if n["id"] not in self.deleted_ids
                for f in n["facts"] if f[0] == pid and f[1] == "event"]

    # ------------------------------------------------------------------ questions
    def _questions(self):
        r = random.Random(self.seed + 1)
        P, Q = self.people, []
        cur = {(p["id"], s): self.current(p["id"], s) for p in P for s in self.slots}

        def ask(kind, text, gold, pid, slot=None, notes=(), **extra):
            Q.append({"qid": f"{kind}-{sum(q['kind'] == kind for q in Q):03d}", "kind": kind, "q": text, "gold": gold,
                      "person": pid, "slot": slot, "notes": sorted(set(n for n in notes if n is not None)),
                      "held_out": slot in HELD_OUT_SLOTS or extra.get("rel") in HELD_OUT_RELS, **extra})

        def qtext(slot, m, pid):     # pid None: the person is not named, so no pronoun hint ("their")
            return SLOTS[slot]["q"].format(m=m, pos=PRON[P[pid]["pron"]][2] if pid is not None else "their")

        def facts_of(pid):
            return [(s, cur[(pid, s)]) for s in self.slots if cur[(pid, s)][0] is not None]
        deleted_keys = {(pid, s) for pid, s, _, _ in self.deleted}
        live = [(p["id"], s) for p in P for s in self.slots if cur[(p["id"], s)][0] is not None]
        r.shuffle(live)
        # named: full name (easy reference)
        for pid, s in live[:150]:
            v, h, n = cur[(pid, s)]
            ask("named", qtext(s, P[pid]["full"], pid), v, pid, s, n[-1:] + [self.intro_note(pid)])
        # role: "my sister"
        for p in P[:N_CLOSE]:
            for s, (v, h, n) in facts_of(p["id"]):
                ask("role", qtext(s, f"my {p['role']}", p["id"]), v, p["id"], s, n[-1:] + [self.intro_note(p["id"])])
        # nick
        nicked = [p for p in P if p["nick"]]
        for p in nicked:
            for s, (v, h, n) in r.sample(facts_of(p["id"]), min(2, len(facts_of(p["id"])))):
                ask("nick", qtext(s, p["nick"], p["id"]), v, p["id"], s, n[-1:] + [self.nick_note(p["id"]),
                                                                                     self.intro_note(p["id"])])
        # fname_ctx: first name shared, circle tells them apart
        fc = Counter((p["first"], p["circle"]) for p in P if p["circle"])
        firsts = Counter(p["first"] for p in P)
        for p in P:
            if p["circle"] and firsts[p["first"]] > 1 and fc[(p["first"], p["circle"])] == 1:
                for s, (v, h, n) in r.sample(facts_of(p["id"]), min(3, len(facts_of(p["id"])))):
                    ask("fname_ctx", qtext(s, f"{p['first']} {CIRCLES[p['circle']][0]}", p["id"]), v, p["id"], s,
                        n[-1:] + [self.intro_note(p["id"])])
        # amb: first name alone, two people share it
        for f, c in firsts.items():
            if c > 1:
                ids = [p["id"] for p in P if p["first"] == f]
                s = r.choice([s for s in self.slots if all(cur[(i, s)][0] for i in ids)] or [None])
                if s:
                    ask("amb", qtext(s, f, None), "", None, s, [self.intro_note(i) for i in ids], people=ids)
        # desc / who: two facts that jointly identify one person, worded with the alternative phrase where one exists
        def descr(s, v):
            canon = [c for c, _, _ in SLOTS[s]["vals"]]
            alt = SLOTS[s]["vals"][canon.index(v)][1]
            return SLOTS[s]["desc"].format(v=v, alt=alt)
        pairs = []
        for p in P:
            fs = facts_of(p["id"])
            for (s1, c1), (s2, c2) in [(x, y) for i, x in enumerate(fs) for y in fs[i + 1:]]:
                match = [q["id"] for q in P if cur[(q["id"], s1)][0] == c1[0] and cur[(q["id"], s2)][0] == c2[0]]
                if match == [p["id"]]:
                    pairs.append((p["id"], s1, c1, s2, c2))
        r.shuffle(pairs)
        used = Counter()
        for pid, s1, c1, s2, c2 in pairs:
            if used[pid] >= 2:
                continue
            rest = [(s, c) for s, c in facts_of(pid) if s not in (s1, s2)]
            if rest and sum(q["kind"] == "desc" for q in Q) < 150:
                s3, (v3, h3, n3) = r.choice(rest)
                m = f"the person who {descr(s1, c1[0])} and {descr(s2, c2[0])}"
                ask("desc", qtext(s3, m, None), v3, pid, s3, c1[2][-1:] + c2[2][-1:] + n3[-1:] + [self.intro_note(pid)])
                used[pid] += 1
            elif sum(q["kind"] == "who" for q in Q) < 150:
                ask("who", f"Who {descr(s1, c1[0])} and {descr(s2, c2[0])}?", P[pid]["full"], pid, None,
                    c1[2][-1:] + c2[2][-1:] + [self.intro_note(pid)])
                used[pid] += 1
        # two-hop: "What pet does my sister's neighbour have?" (the anchor by role, full name or nickname)
        for p in r.sample(P, len(P)):
            for rel, b, way in p["links"]:
                if not self.unique_link(p["id"], rel) or (way == "in" and not RELS[rel][0]):
                    continue
                if sum(q["kind"] == "two" for q in Q) >= 180:
                    break
                fs = facts_of(b)
                if not fs:
                    continue
                s, (v, h, n) = r.choice(fs)
                anchor = f"my {p['role']}" if p["role"] else (p["nick"] if p["nick"] and r.random() < 0.3 else p["full"])
                noun = RELS[rel][3]
                pid_note = self.rel_note(p["id"], rel, b) if way == "out" else self.rel_note(b, rel, p["id"])
                ask("two", qtext(s, f"{anchor}'s {noun}", b), v, b, s, n[-1:] + [pid_note, self.intro_note(p["id"]),
                                                                                  self.intro_note(b)],
                    anchor=p["id"], rel=rel)
        # updates: the current value after at least one change
        upd = [(pid, s) for pid, s in live if cur[(pid, s)][1]]
        for pid, s in upd[:180]:
            v, h, n = cur[(pid, s)]
            m = f"my {P[pid]['role']}" if P[pid]["role"] else P[pid]["full"]
            form = next(nn["form"] for nn in reversed(self.notes) if nn["id"] in n and nn["form"] in
                        ("plain", "change", "fix", "repeat", "init"))
            ask("upd", qtext(s, m, pid).replace("?", " now?"), v, pid, s, n[-2:] + [self.intro_note(pid)], old=h,
                form=form)
        # retractions
        for p in P:
            for s, d in p.get("retracted", {}).items():
                v, h, n = self.current(p["id"], s)
                if v is not None:                               # never ask a retraction the notes later undo
                    continue
                m = f"my {p['role']}" if p["role"] else p["full"]
                last = [x for x in self.notes if x["id"] in n]
                ask("retract", qtext(s, m, p["id"]), "", p["id"], s, [x["id"] for x in last[-2:]] +
                    [self.intro_note(p["id"])], old=[f[2] for x in last for f in x["facts"] if f[2]])
        # deleted facts: the right answer is that the notes don't say; naming the value is a leak
        for pid, s, nid, val in self.deleted:
            m = f"my {P[pid]['role']}" if P[pid]["role"] else P[pid]["full"]
            ask("deleted", qtext(s, m, pid), "", pid, s, [self.intro_note(pid)], leak=val)
        # events
        for p in P:
            ev = sorted(self.events(p["id"]))
            if not ev:
                continue
            m = f"my {p['role']}" if p["role"] else p["full"]
            last = ev[-1]
            ask("event_last", f"When did I last meet up with {m}?", last[0], p["id"], "event",
                [last[2], self.intro_note(p["id"])])
            months = Counter(e[0][:7] for e in ev)
            for e in ev:
                if months[e[0][:7]] == 1 and r.random() < 0.6:
                    y, mo = e[0][:7].split("-")
                    ask("event_what", f"What did {m} and I do together in {MONTHS[int(mo) - 1]} {y}?", e[1], p["id"],
                        "event", [e[2], self.intro_note(p["id"])])
        by_act_month = defaultdict(list)
        for p in P:
            for e in self.events(p["id"]):
                by_act_month[(e[1], e[0][:7])].append((p["id"], e))
        for (act, ym), lst in by_act_month.items():
            if len(lst) == 1 and r.random() < 0.8:
                pid, e = lst[0]
                y, mo = ym.split("-")
                ask("event_who", f"Who did I {dict(ACTIVITY_VERB)[act]} with in {MONTHS[int(mo) - 1]} {y}?",
                    P[pid]["full"], pid, "event", [e[2], self.intro_note(pid)], act=act)
        return Q


ACTIVITY_VERB = [("dinner", "have dinner"), ("hike", "go hiking"), ("cinema", "see a film"), ("coffee", "grab coffee"),
                 ("concert", "go to a concert"), ("museum", "go to the science museum"), ("swim", "go swimming"),
                 ("market", "go to the farmers' market"), ("football match", "watch a football match"),
                 ("game night", "have a board game night"), ("picnic", "have a picnic"), ("karaoke", "do karaoke")]
HARD = ["role", "nick", "fname_ctx", "desc", "who", "two", "upd", "retract", "deleted", "event_last", "event_what",
        "event_who"]
ASSOC = ["desc", "who", "two"]                  # the kinds the owner's association idea is judged on
EVENT_KINDS = ["event_last", "event_what", "event_who"]


def value_keys(slot, v):
    for c, alt, keys in SLOTS[slot]["vals"]:
        if c == v:
            return keys
    return [v.lower()]


def check(world):
    """Self-checks: every question's gold notes exist and are not deleted; no two questions share a text."""
    W, errs = world, []
    dup = [t for t, k in Counter(q["q"] for q in W.questions).items() if k > 1]
    errs += [f"question text asked twice: {t}" for t in dup]
    for q in W.questions:
        for n in q["notes"]:
            if n in W.deleted_ids:
                errs.append(f"{q['qid']}: gold note {n} is deleted")
        if q["kind"] not in ("amb", "deleted") and not q["notes"]:
            errs.append(f"{q['qid']}: no gold notes")
    # a deleted value must not survive in any other note mentioning that person
    for pid, s, nid, val in W.deleted:
        keys = value_keys(s, val)
        for n in W.notes:
            if n["id"] != nid and n["id"] not in W.deleted_ids and any(m[1] == pid for m in n["mentions"]) and \
                    any(k in n["text"].lower() for k in keys):
                errs.append(f"deleted value {val} of person {pid} survives in note {n['id']}")
    return errs


def stats(W):
    styles = Counter(m[2] for n in W.notes for m in n["mentions"])
    per_close = Counter(m[1] for n in W.notes for m in n["mentions"] if m[1] < N_CLOSE)
    return {"split": W.split, "people": len(W.people), "notes": len(W.notes), "deleted": len(W.deleted_ids),
            "note_types": dict(Counter(n["type"] for n in W.notes)), "mention_styles": dict(styles),
            "notes_per_close_person": [per_close[i] for i in range(N_CLOSE)],
            "questions": dict(Counter(q["kind"] for q in W.questions)),
            "held_out_questions": sum(q["held_out"] for q in W.questions),
            "update_forms": dict(Counter(q.get("form") for q in W.questions if q["kind"] == "upd")),
            "chars": sum(len(n["text"]) + 14 for n in W.notes)}


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--split", default="dev", choices=list(SEEDS))
    ap.add_argument("--samples", type=int, default=25)
    a = ap.parse_args()
    W = World(a.split)
    print(json.dumps(stats(W), indent=1))
    errs = check(W)
    print(f"self-check: {len(errs)} problems", *errs[:10], sep="\n")
    r = random.Random(0)
    for n in r.sample(W.notes, a.samples):
        print(f"[{n['date']}] #{n['id']} {n['text']}")
    for kind in sorted(set(q["kind"] for q in W.questions)):
        q = next(q for q in W.questions if q["kind"] == kind)
        print(f"{kind}: {q['q']} -> {q['gold'] or q.get('leak', '(none)')}")


if __name__ == "__main__":
    main()
